<script setup lang="ts">
import{computed,reactive,ref}from'vue';import{useQuery}from'@tanstack/vue-query';import{useRouter}from'vue-router';import AsyncStatePanel from '@/components/AsyncStatePanel.vue';import{riskLabel,formatTime}from'@/features/global-impact/model/presentation';import{workspaceAssetApi,type Filters,type WorkspaceLifecycle}from'../api/workspaceAssetApi';import type{RiskLevel}from'@/features/global-impact/api/globalImpactApi'
const router=useRouter();const draft=reactive<{keyword:string;environmentCode:string;lifecycleStatus:WorkspaceLifecycle|'';riskLevel:RiskLevel|''}>({keyword:'',environmentCode:'',lifecycleStatus:'',riskLevel:''});const applied=ref<Filters>({page:0,size:20});const data=useQuery({queryKey:computed(()=>['workspace-assets',applied.value]),queryFn:({signal})=>workspaceAssetApi.workspaces(applied.value,signal)});function search(){applied.value={...draft,page:0,size:20}}function reset(){draft.keyword='';draft.environmentCode='';draft.lifecycleStatus='';draft.riskLevel='';search()}function page(v:number){applied.value={...applied.value,page:v-1}}
</script>
<template><section><div class="page-heading"><div><h2>Workspace 资产</h2><p>追溯环境、风险、有效治理策略、验证基线和漂移态势。</p></div><el-button :loading="data.isFetching.value" @click="data.refetch()">刷新资产</el-button></div><div class="surface"><div class="workspace-filter"><el-input v-model="draft.keyword" clearable placeholder="Workspace 编码、名称或负责人" @keyup.enter="search"/><el-input v-model="draft.environmentCode" clearable placeholder="环境"/><el-select v-model="draft.lifecycleStatus" clearable placeholder="全部生命周期"><el-option v-for="v in ['DRAFT','VERIFIED','IN_REVIEW','APPROVED','COMPILED']" :key="v" :label="v" :value="v"/></el-select><el-select v-model="draft.riskLevel" clearable placeholder="全部风险"><el-option v-for="(label,v) in riskLabel" :key="v" :label="label" :value="v"/></el-select><el-button type="primary" @click="search">查询</el-button><el-button @click="reset">重置</el-button></div><AsyncStatePanel :loading="data.isPending.value" :error="data.isError.value" loading-label="正在加载 Workspace" error-title="Workspace 资产读取失败" @retry="data.refetch()"><template v-if="data.data.value"><el-empty v-if="!data.data.value.items.length" description="当前范围内没有 Workspace"/><el-table v-else :data="data.data.value.items" row-key="workspaceId"><el-table-column label="Workspace" min-width="240"><template #default="{row}"><button class="link-button" @click="router.push(`/workspaces/${row.workspaceId}`)">{{row.workspaceName}}</button><div class="subtle mono" style="margin-top:4px;font-size:10px">{{row.workspaceCode}} · {{row.environmentCode}}</div></template></el-table-column><el-table-column prop="lifecycleStatus" label="生命周期" width="115"/><el-table-column label="风险" width="105"><template #default="{row}"><el-tag :type="row.riskLevel==='CRITICAL'||row.riskLevel==='HIGH'?'danger':'info'">{{riskLabel[row.riskLevel as RiskLevel]}}</el-tag></template></el-table-column><el-table-column label="有效策略" min-width="210"><template #default="{row}"><template v-if="row.effectivePolicy"><button class="link-button" @click="router.push(`/governance-policies/${row.effectivePolicy.policyId}/versions/${row.effectivePolicy.versionId}`)">{{row.effectivePolicy.policyName}} · v{{row.effectivePolicy.versionNo}}</button><div class="subtle" style="font-size:10px;margin-top:4px">来源 {{row.effectivePolicy.resolutionSource}}</div></template><span v-else>系统默认</span></template></el-table-column><el-table-column label="基线" width="100"><template #default="{row}">{{row.latestBaseline?`#${row.latestBaseline.baselineId}`:'—'}} / {{row.baselineCount}}</template></el-table-column><el-table-column label="漂移" width="120"><template #default="{row}"><b>{{row.driftSummary.actionableCount}}</b> 待处置<div class="subtle" style="font-size:10px">{{row.driftSummary.changedItemCount}} 变更项</div></template></el-table-column><el-table-column label="更新" width="170"><template #default="{row}">{{formatTime(row.updatedAt)}}</template></el-table-column><el-table-column label="操作" width="80" fixed="right"><template #default="{row}"><el-button link type="primary" @click="router.push(`/workspaces/${row.workspaceId}`)">追溯</el-button></template></el-table-column></el-table><div class="policy-pagination"><span>共 {{data.data.value.totalElements}} 个 Workspace</span><el-pagination background layout="prev,pager,next" :page-size="data.data.value.size" :total="data.data.value.totalElements" :current-page="data.data.value.page+1" @current-change="page"/></div></template></AsyncStatePanel></div></section></template>
